/// Keeps a trailing line comment that follows the opening brace of a `case`
/// clause's hugging block body on the same line as the `case` clause.
///
/// A `case` whose body is a single block statement hugs the opening brace onto
/// the `case` line. When the source has the comment *before* the brace, it is
/// printed as a line suffix on that line:
///
/// ```javascript
/// switch (key) {
///     case foo: // comment
///     {
///         break;
///     }
/// }
/// ```
///
/// is formatted as:
///
/// ```javascript
/// switch (key) {
///     case foo: { // comment
///         break;
///     }
/// }
/// ```
///
/// On a second formatting pass the comment now follows the `{` and would, by
/// default, become a leading comment of the first statement and be moved onto
/// its own line inside the block, breaking idempotency. This handler re-attaches
/// it as a trailing comment of the case's test expression so it is printed on
/// the `case` line exactly like the first pass.
fn handle_switch_case_clause_block_comment(
    comment: DecoratedComment<JsLanguage>,
) -> CommentPlacement<JsLanguage> {
    // Only relevant for a line comment that directly follows the `{` (i.e. it
    // has no preceding node inside the block).
    if !comment.kind().is_line() || comment.preceding_node().is_some() {
        return CommentPlacement::Default(comment);
    }

    let Some(block) = JsBlockStatement::cast_ref(comment.enclosing_node()) else {
        return CommentPlacement::Default(comment);
    };

    // The block must be the single (hugging) body of a `case` clause.
    let Some(case_clause) = block
        .syntax()
        .grand_parent()
        .and_then(JsCaseClause::cast)
    else {
        return CommentPlacement::Default(comment);
    };

    if !is_single_block_statement_consequent(&case_clause) {
        return CommentPlacement::Default(comment);
    }

    match case_clause.test() {
        Ok(test) => CommentPlacement::trailing(test.into_syntax(), comment),
        Err(_) => CommentPlacement::Default(comment),
    }
}

/// Returns `true` when the `case` clause's body is a single block statement that
/// hugs the opening brace onto the `case` line (mirrors the check in the
/// `JsCaseClause` formatter).
fn is_single_block_statement_consequent(case_clause: &JsCaseClause) -> bool {
    let consequent = case_clause.consequent();

    matches!(
        consequent.iter().next(),
        Some(AnyJsStatement::JsBlockStatement(_))
    ) && consequent
        .iter()
        .filter(|statement| !matches!(statement, AnyJsStatement::JsEmptyStatement(_)))
        .count()
        == 1
