389	/// Keeps a trailing line comment that follows the opening brace of a `case`
390	/// clause's hugging block body on the same line as the `case` clause.
391	///
392	/// A `case` whose body is a single block statement hugs the opening brace onto
393	/// the `case` line. When the source has the comment *before* the brace, it is
394	/// printed as a line suffix on that line:
395	///
396	/// ```javascript
397	/// switch (key) {
398	///     case foo: // comment
399	///     {
400	///         break;
401	///     }
402	/// }
403	/// ```
404	///
405	/// is formatted as:
406	///
407	/// ```javascript
408	/// switch (key) {
409	///     case foo: { // comment
410	///         break;
411	///     }
412	/// }
413	/// ```
414	///
415	/// On a second formatting pass the comment now follows the `{` and would, by
416	/// default, become a leading comment of the first statement and be moved onto
417	/// its own line inside the block, breaking idempotency. This handler re-attaches
418	/// it as a trailing comment of the case's test expression so it is printed on
419	/// the `case` line exactly like the first pass.
420	fn handle_switch_case_clause_block_comment(
421	    comment: DecoratedComment<JsLanguage>,
422	) -> CommentPlacement<JsLanguage> {
423	    // Only relevant for a line comment that directly follows the `{` (i.e. it
424	    // has no preceding node inside the block).
425	    if !comment.kind().is_line() || comment.preceding_node().is_some() {
426	        return CommentPlacement::Default(comment);
427	    }
428	
429	    let Some(block) = JsBlockStatement::cast_ref(comment.enclosing_node()) else {
430	        return CommentPlacement::Default(comment);
431	    };
432	
433	    // The block must be the single (hugging) body of a `case` clause.
434	    let Some(case_clause) = block
435	        .syntax()
436	        .grand_parent()
437	        .and_then(JsCaseClause::cast)
438	    else {
439	        return CommentPlacement::Default(comment);
440	    };
441	
442	    if !is_single_block_statement_consequent(&case_clause) {
443	        return CommentPlacement::Default(comment);
444	    }
445	
446	    match case_clause.test() {
447	        Ok(test) => CommentPlacement::trailing(test.into_syntax(), comment),
448	        Err(_) => CommentPlacement::Default(comment),
449	    }
450	}
